import React, { useState, useEffect, useRef } from "react";
import Chart from 'chart.js/auto';

// --- DATOS INICIALES Y CONSTANTES (Sin cambios) ---
const initialExpenses = [
  { id: 1, date: "2023-08-10", category: "arriendo", amount: 1200000, description: "Arriendo oficina central" },
  { id: 2, date: "2023-08-05", category: "servicios", amount: 150000, description: "Pago de servicios básicos" },
];
const defaultCategories = ["arriendo", "servicios", "insumos", "sueldos", "imprevistos"];
const defaultPaymentMethods = ["efectivo", "transferencia", "tarjeta"];

function ExpensesPage() {
  // --- ESTADOS (Se añade uno para el modal del formulario) ---
  const [expenses, setExpenses] = useState(() => JSON.parse(localStorage.getItem("expenses") || JSON.stringify(initialExpenses)));
  const [categories, setCategories] = useState(() => JSON.parse(localStorage.getItem("expenseCategories") || JSON.stringify(defaultCategories)));
  const [form, setForm] = useState({ date: "", category: "", amount: "", paymentMethod: "", description: "" });
  const [filters, setFilters] = useState({ category: "", paymentMethod: "", search: "" });
  const [showAddModal, setShowAddModal] = useState(false); // <-- NUEVO
  const [showEditModal, setShowEditModal] = useState(false);
  const [editExpense, setEditExpense] = useState(null);
  // ...otros estados sin cambios
  const monthlyChartRef = useRef(null);
  const monthlyChartInstance = useRef(null);
  const categoryChartRef = useRef(null);
  const categoryChartInstance = useRef(null);

  // --- LÓGICA DE useEffect (CON GRÁFICOS NUEVOS) ---
  useEffect(() => {
    // --- GRÁFICO DE LÍNEAS MENSUAL (NUEVO TIPO) ---
    if (monthlyChartInstance.current) monthlyChartInstance.current.destroy();
    const now = new Date();
    const monthLabels = Array.from({ length: 6 }, (_, i) => {
      const d = new Date(now.getFullYear(), now.getMonth() - 5 + i, 1);
      return d.toLocaleString('es-CL', { month: 'short', year: 'numeric' });
    });
    const monthlyTotals = Array.from({ length: 6 }, (_, i) => {
        const d = new Date(now.getFullYear(), now.getMonth() - 5 + i, 1);
        const key = `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}`;
        return expenses.filter(e => e.date?.startsWith(key)).reduce((sum, e) => sum + Number(e.amount), 0);
    });
    if (monthlyChartRef.current) {
      monthlyChartInstance.current = new Chart(monthlyChartRef.current, {
        type: 'line', // <-- CAMBIO DE GRÁFICO
        data: {
          labels: monthLabels,
          datasets: [{
            label: 'Gastos',
            data: monthlyTotals,
            borderColor: '#3b82f6',
            backgroundColor: 'rgba(59, 130, 246, 0.1)',
            fill: true,
            tension: 0.3,
          }],
        },
      });
    }

    // --- GRÁFICO DE BARRAS HORIZONTALES POR CATEGORÍA (NUEVO TIPO) ---
    if (categoryChartInstance.current) categoryChartInstance.current.destroy();
    const catTotals = expenses.reduce((acc, e) => {
        acc[e.category] = (acc[e.category] || 0) + Number(e.amount);
        return acc;
    }, {});
    const catLabels = Object.keys(catTotals).map(c => c.charAt(0).toUpperCase() + c.slice(1));
    const catData = Object.values(catTotals);
    if (categoryChartRef.current) {
      categoryChartInstance.current = new Chart(categoryChartRef.current, {
        type: 'bar', // <-- CAMBIO DE GRÁFICO
        data: {
          labels: catLabels,
          datasets: [{
            label: 'Total por Categoría',
            data: catData,
            backgroundColor: '#10b981',
          }],
        },
        options: {
          indexAxis: 'y', // <-- ESTO LO HACE HORIZONTAL
          plugins: { legend: { display: false } },
        },
      });
    }
  }, [expenses]);
  
  // --- LÓGICA DE FILTROS Y HANDLERS (Sin cambios importantes) ---
  const filteredExpenses = expenses.filter(e => {
    return (filters.category ? e.category === filters.category : true) &&
           (filters.search ? e.description.toLowerCase().includes(filters.search.toLowerCase()) : true);
  });
  
  const handleSubmit = (e) => {
    e.preventDefault();
    const newExpense = { ...form, id: Date.now() };
    setExpenses([...expenses, newExpense]);
    setForm({ date: "", category: "", amount: "", paymentMethod: "", description: "" });
    setShowAddModal(false); // Cierra el modal
  };

  // ...otros handlers...

  // --- RENDERIZADO DEL NUEVO DISEÑO ---
  return (
    <div className="bg-gray-100 min-h-screen font-sans">
      <div className="container mx-auto p-4 sm:p-6 lg:p-8">
        <header className="flex flex-col sm:flex-row justify-between items-center mb-8">
          <h1 className="text-3xl font-bold text-gray-800">Panel de Gastos</h1>
          <button
            onClick={() => setShowAddModal(true)}
            className="mt-4 sm:mt-0 w-full sm:w-auto bg-blue-600 text-white font-bold py-3 px-6 rounded-lg shadow-md hover:bg-blue-700 transition-colors"
          >
            + Registrar Gasto
          </button>
        </header>

        {/* Sección de Gráficos */}
        <section className="grid grid-cols-1 lg:grid-cols-5 gap-6 mb-8">
          <div className="lg:col-span-3 bg-white p-6 rounded-lg shadow-sm">
            <h2 className="text-xl font-semibold text-gray-700 mb-4">Tendencia de Gastos (Últimos 6 meses)</h2>
            <canvas ref={monthlyChartRef}></canvas>
          </div>
          <div className="lg:col-span-2 bg-white p-6 rounded-lg shadow-sm">
            <h2 className="text-xl font-semibold text-gray-700 mb-4">Total por Categoría</h2>
            <canvas ref={categoryChartRef}></canvas>
          </div>
        </section>

        {/* Filtros */}
        <section className="bg-white p-4 rounded-lg shadow-sm mb-6">
            <div className="flex flex-col sm:flex-row gap-4">
                <input type="text" name="search" onChange={(e) => setFilters({...filters, search: e.target.value})} placeholder="Buscar por descripción..." className="flex-grow border-gray-300 rounded-md p-2"/>
                <select name="category" onChange={(e) => setFilters({...filters, category: e.target.value})} className="border-gray-300 rounded-md p-2">
                    <option value="">Todas las Categorías</option>
                    {categories.map(c => <option key={c} value={c}>{c.charAt(0).toUpperCase() + c.slice(1)}</option>)}
                </select>
            </div>
        </section>

        {/* Listado de Tarjetas de Gastos */}
        <section className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
          {filteredExpenses.map(g => (
            <div key={g.id} className="bg-white rounded-lg shadow-sm p-5 flex flex-col justify-between">
              <div>
                <div className="flex justify-between items-start mb-2">
                  <span className="text-sm font-semibold text-gray-500">{g.date}</span>
                  <span className="bg-blue-100 text-blue-800 text-xs font-semibold px-2.5 py-0.5 rounded-full">{g.category}</span>
                </div>
                <p className="text-gray-700 mb-2">{g.description || "Sin descripción"}</p>
              </div>
              <div className="mt-4 flex justify-between items-end">
                  <p className="text-2xl font-bold text-gray-800">${Number(g.amount).toLocaleString('es-CL')}</p>
                  <div>
                      {/* Botones de Editar/Eliminar */}
                  </div>
              </div>
            </div>
          ))}
        </section>

        {/* Modal para Agregar Gasto */}
        {showAddModal && (
          <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50">
            <div className="bg-white rounded-lg shadow-2xl p-8 w-full max-w-md">
              <h2 className="text-2xl font-bold mb-6">Registrar Nuevo Gasto</h2>
              <form onSubmit={handleSubmit} className="space-y-4">
                  {/* Inputs del formulario */}
                  <input type="date" name="date" onChange={(e) => setForm({...form, date: e.target.value})} className="w-full border-gray-300 border rounded-md p-3" required />
                  <select name="category" onChange={(e) => setForm({...form, category: e.target.value})} className="w-full border-gray-300 border rounded-md p-3" required>
                    <option value="">Seleccionar Categoría</option>
                    {categories.map(c=><option key={c} value={c}>{c.charAt(0).toUpperCase() + c.slice(1)}</option>)}
                  </select>
                  <input type="number" name="amount" placeholder="Monto" onChange={(e) => setForm({...form, amount: e.target.value})} className="w-full border-gray-300 border rounded-md p-3" required />
                  <input type="text" name="description" placeholder="Descripción" onChange={(e) => setForm({...form, description: e.target.value})} className="w-full border-gray-300 border rounded-md p-3" />
                  <div className="flex justify-end gap-4 pt-4">
                      <button type="button" onClick={() => setShowAddModal(false)} className="px-6 py-2 bg-gray-200 text-gray-800 rounded-md">Cancelar</button>
                      <button type="submit" className="px-6 py-2 bg-blue-600 text-white rounded-md">Guardar</button>
                  </div>
              </form>
            </div>
          </div>
        )}
      </div>
    </div>
  );
}

export default ExpensesPage;
